import{_ as a,o as l,c as n,aw as o}from"./chunks/framework.DLufY-ao.js";const A=JSON.parse('{"title":"Repaint & Reflow","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/critical-rendering-path/rendering/repaint-and-reflow.md","filePath":"wiki/dev-commit/js/critical-rendering-path/rendering/repaint-and-reflow.md"}'),e={name:"wiki/dev-commit/js/critical-rendering-path/rendering/repaint-and-reflow.md"};function p(t,s,r,i,c,y){return l(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="repaint-reflow" tabindex="-1">Repaint &amp; Reflow <a class="header-anchor" href="#repaint-reflow" aria-label="Permalink to &quot;Repaint &amp; Reflow&quot;">​</a></h1><ul><li>Repaint и Reflow блокируют браузер и не пользователь, и не ваше веб-приложение не смогут ничего сделать во время reflow и repaint. В крайних случаях CSS эффекты могут затормозить выполнение JavaScript&#39;а. Это одна из причин, почему вы сталкиваетесь с дергающейся прокруткой страницы и неотзывчивым интерфейсом</li></ul><h2 id="repaint-restyle" tabindex="-1">Repaint (Restyle) <a class="header-anchor" href="#repaint-restyle" aria-label="Permalink to &quot;Repaint (Restyle)&quot;">​</a></h2><ul><li><strong>Repaint</strong> (Перерисовка) - в случае изменения стилей элемента, не влияющих на его размеры и положение на странице: background-color, border-color, visibility, opacity, outline и т.д.</li><li>Браузер просто отрисовывает его заново, с учётом нового стиля</li></ul><h2 id="reflow-relayout" tabindex="-1">Reflow (Relayout) <a class="header-anchor" href="#reflow-relayout" aria-label="Permalink to &quot;Reflow (Relayout)&quot;">​</a></h2><ul><li><strong>Reflow</strong> (Перекомпановка) - если изменения затрагивают содержимое, структуру документа, положение элементов, происходит перерасчет позиций и размеров всех элементов, что приводит к полной или частичной повторной отрисовке страницы</li><li>Изменения в одном элементе могут повлиять на все дочерние, родительские или смежные элементы</li></ul><h3 id="когда-запускается-reflow" tabindex="-1">Когда запускается reflow <a class="header-anchor" href="#когда-запускается-reflow" aria-label="Permalink to &quot;Когда запускается reflow&quot;">​</a></h3><ul><li>Манипуляции с DOM (добавление, удаление, изменение, перестановка ВИДИМЫХ элементов)</li><li>Расчёт или изменение CSS-свойств (н-р: изменив ширину элемента, вы можете повлиять на все элементы того же уровня в DOM и окружающие его элементы)</li><li>Добавление, удаление таблиц стилей</li><li>Манипуляции с атрибутом «class»</li><li>CSS3 анимация и свойство transition (каждый кадр анимации вызывает reflow)</li><li>Использование offsetWidth и OffsetHeight (при попытке считать значения offsetWidth и offsetHeight элемента для их вычисления может быть запущен reflow)</li><li>Изменение содержимого, в т.ч. текста в полях форм</li><li>Манипуляции с окном браузера - изменения размеров, прокрутка</li><li>Активация псевдо-классов (например, :hover)</li><li>Изменении размера шрифта</li></ul><h2 id="оптимизация-со-стороны-браузера" tabindex="-1">Оптимизация со стороны браузера <a class="header-anchor" href="#оптимизация-со-стороны-браузера" aria-label="Permalink to &quot;Оптимизация со стороны браузера&quot;">​</a></h2><ol><li>Браузеры по возможности локализуют repaint и reflow в пределах элементов, подвергнувшимися изменению. Например, изменение размеров абсолютно или фиксировано спозиционированного элемента затронет только сам элемент и его потомков, в то время как изменение статично спозиционированного - повлечет reflow всех элементов, следующих за ним</li><li>Во время выполнения JavaScript браузеры кэшируют вносимые изменения, и применяют их в один проход по завершению работы блока кода</li></ol><ul><li>В ходе выполнения данного кода произойдет только один reflow и repaint:</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> $body</span><span style="color:#0184BC;"> =</span><span style="color:#4078F2;"> $</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;body&#39;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;padding&#39;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&#39;1px&#39;</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// reflow, repaint</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;color&#39;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&#39;red&#39;</span><span style="color:#383A42;">);   </span><span style="color:#A0A1A7;font-style:italic;">// repaint</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;margin&#39;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&#39;2px&#39;</span><span style="color:#383A42;">);  </span><span style="color:#A0A1A7;font-style:italic;">// reflow, repaint</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// На самом деле произойдет только 1 reflow и repaint</span></span></code></pre></div><hr><ul><li>Но, как описано выше, обращение к свойствам элементов вызовет принудительный reflow. То есть, если мы в приведённый блок кода добавим обращение к свойству элемента, это вызовет лишний reflow:</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> $body</span><span style="color:#0184BC;"> =</span><span style="color:#4078F2;"> $</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;body&#39;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;padding&#39;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&#39;1px&#39;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// обращение к свойству, принудительный reflow</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;padding&#39;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;color&#39;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&#39;red&#39;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;margin&#39;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&#39;2px&#39;</span><span style="color:#383A42;">);</span></span></code></pre></div>`,15)])])}const f=a(e,[["render",p]]);export{A as __pageData,f as default};
